SELECT CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END AS category, COALESCE(SUM(t.amount), 0) AS spentAmount FROM TRANSACTIONS t
WHERE t.user_id = #{userId} AND t.type = 'EXPENSE' AND t.category NOT IN ('INCOME', 'SEND', 'CARD_WITHDRAWAL', 'LOAN_REPAYMENT') AND t.transaction_date BETWEEN #{startDate} AND #{endDate}
GROUP BY CASE WHEN t.category IN ('OTHER', 'ETC') THEN 'ETC' ELSE t.category END ORDER BY category ASC

SELECT COALESCE(SUM(t.amount), 0)
FROM TRANSACTIONS t

WHERE t.user_id = #{userId}
  AND t.type = 'EXPENSE'
  AND t.category NOT IN ('INCOME', 'SEND', 'CARD_WITHDRAWAL', 'LOAN_REPAYMENT')
  AND t.transaction_date BETWEEN #{startDate} AND #{endDate}
